values ((select s.id from public.sessions s join public.topics t on t.id = s.topic_id where t.slug = 'ai-tools-landscape' and s.order_index = 1),
  'Your whole team works in Excel, Outlook and Teams every day. Which kind of assistant is most convenient to try first?', '["One built into Microsoft 365","A voice cloning tool","A video editor","An image generator"]'::jsonb, 0, 'An assistant that lives inside the apps you already use sits right next to your files and workflow.', 1);
